function addStd(){if(S.stdv>=1)return;const L=[T('uri','Urine - Leukocyte esterase','Negative'),T('uri','Urine - Urobilinogen','Normal'),T('uri','Urine - Yeast cells','Nil'),T('uri','Urine - Mucus','Nil'),T('sto','Stool - Reaction',''),T('sto','Stool - Undigested food','Nil'),T('sto','Stool - Fat globules','Nil'),T('sto','Stool - Yeast cells','Nil'),N('coag','PT Control (Normal)','sec','',''),N('coag','PT Concentration','%','','')];L.forEach(x=>{if(!S.tests.some(t=>String(t.name).toLowerCase()===x.name.toLowerCase())){x.id=uid('i');S.tests.push(x)}});S.stdv=1;save()}
function applyDefR(){if(S.rngv)return;const m={};DEFR.split(';').forEach(r=>{const a=r.split('|');m[nk(a[0])]=a});const n=new Set(DEFN.split(';').map(nk));
 S.tests.forEach(t=>{const a=m[nk(t.name)];if(t.type==='num'&&a&&t.low===''&&t.high===''&&t.lowF===''&&t.highF===''){t.low=a[1];t.high=a[2];t.lowF=a[3]||'';t.highF=a[4]||'';t.rdef=1}
  else if(t.type==='txt'&&n.has(nk(t.name))&&!t.normal){t.normal='Negative';t.rdef=1}});S.rngv=1;save()}
